def is_prime_hexadecimal_digit(digit):
    primes = ['2', '3', '5', '7', 'B', 'D']
    return digit in primes

def hex_key(num):
    prime_count = 0
    for digit in num:
        if is_prime_hexadecimal_digit(digit):
            prime_count += 1
    return prime_count

