def match_parens(lst):
    def is_balanced(s):
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    if len(lst) != 2 or not all(isinstance(s, str) for s in lst):
        return 'No'

    s1, s2 = lst[0], lst[1]
    possible_orders = [s1 + s2, s2 + s1]

    for order in possible_orders:
        if is_balanced(order):
            return 'Yes'

    return 'No'

