import math

def triangle_area(a, b, c):
    # Validate the input values to ensure they are positive integers
    if not all(isinstance(side, int) and side > 0 for side in [a, b, c]):
        return -1

    # Check if the input values can form a valid triangle by applying the triangle inequality theorem
    if a + b <= c or a + c <= b or b + c <= a:
        return -1

    # If the triangle is valid, calculate the area using Heron's formula
    s = (a + b + c) / 2
    area = math.sqrt(s * (s - a) * (s - b) * (s - c))

    # Round the area to two decimal places and return it, otherwise return -1
    return round(area, 2)
