        "earth": 3,
        "mars": 4,
        "jupiter": 5,
        "saturn": 6,
        "uranus": 7,
        "neptune": 8
    }

    planet1 = planet1.lower()
    planet2 = planet2.lower()

    if planet1 not in planets or planet2 not in planets:
        return ()

