    # Step 2: Calculate the semi-perimeter
    s = (a + b + c) / 2

    # Step 3: Calculate the area using Heron's formula
    area = math.sqrt(s * (s - a) * (s - b) * (s - c))

    # Step 4: Round the area to two decimal places
    area = round(area, 2)

    # Step 5: Return the area or -1 if the triangle is not valid
    return area
